// Process each course record one by one
// n8n automatically processes each record when 'Return All' is enabled
const record = $input.item.json;

// Extract fields from Airtable record structure
// Fields are directly on the record object, not nested under 'fields'
const targetUrl = record.target_url || record['target_url'] || '';

// Only process records that have a targetUrl (filter invalid records)
if (!targetUrl || targetUrl.trim() === '') {
  // Return null to skip this record (n8n will filter it out)
  return null;
}

const courseData = {
  recordId: record.id || '',
  courseTitle: record.course_title || record['course_title'] || 'No title',
  targetUrl: targetUrl,
  createdAt: record.createdTime || record['createdTime'] || record.created_at || '',
  image: record.image || record['image'] || null
};

// Return the processed data
return courseData;

// Filter out null/empty records (those without targetUrl)
const item = $input.item.json;

// If the item is null or doesn't have targetUrl, skip it
if (!item || !item.targetUrl || item.targetUrl.trim() === '') {
  return null;
}

// Return valid records
return item;

// Convert base64 image to binary for WhatsApp
const item = $input.item.json;

// Prepare message text
const messageText = `*${item.courseTitle || 'No title'}*

🔗 Course Link: ${item.targetUrl || ''}`;

// Prepare binary data for image if available
let binaryData = {};
if (item.image && item.image.startsWith('data:image')) {
  try {
    // Extract base64 data and mime type from data URL
    const matches = item.image.match(/data:image\/([^;]+);base64,(.+)/);
    if (matches && matches[2]) {
      const mimeType = matches[1] || 'jpeg';
      const base64Data = matches[2];

      // Convert base64 to Buffer for binary data
      const imageBuffer = Buffer.from(base64Data, 'base64');

      // Create binary data for n8n (must be named 'data' for WhatsApp node)
      binaryData = {
        data: {
          data: imageBuffer.toString('base64'),
          mimeType: `image/${mimeType}`,
          fileName: `course-image.${mimeType === 'png' ? 'png' : 'jpg'}`
        }
      };
    }
  } catch (error) {
    console.log('Error processing image:', error);
  }
}

// Return JSON data and binary data
const result = {
  json: {
    courseTitle: item.courseTitle || 'No title',
    targetUrl: item.targetUrl || '',
    messageText: messageText,
    hasImage: Object.keys(binaryData).length > 0
  }
};

// Add binary data if available
if (Object.keys(binaryData).length > 0) {
  result.binary = binaryData;
}

return result;
